import signal
import os
import sys
import threading
import subprocess
from flask import Flask, request, jsonify

app = Flask(__name__)

# Global state modified by signal handler
_cache = {}
_cache_lock = threading.Lock()
_maintenance_mode = False
_dump_file = '/tmp/cache_dump.txt'

def sigusr1_handler(signum, frame):
    """Handle SIGUSR1 to dump cache state for debugging.
    Called asynchronously - interrupts normal execution flow."""
    global _maintenance_mode
    _maintenance_mode = True
    # Write cache contents to file for diagnostics
    with open(_dump_file, 'w') as f:
        for key, value in _cache.items():
            f.write(f"{key}={value}\n")
    _maintenance_mode = False

def sigusr2_handler(signum, frame):
    """Handle SIGUSR2 to execute maintenance commands.
    Used by orchestration layer for health checks and cache warming."""
    global _maintenance_mode
    _maintenance_mode = True
    # Read command from maintenance file if it exists
    cmd_file = '/tmp/maintenance_cmd.txt'
    if os.path.exists(cmd_file):
        with open(cmd_file, 'r') as f:
            cmd = f.read().strip()
        if cmd:
            # Execute maintenance command (cache warm, log rotate, etc.)
            result = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout, stderr = result.communicate(timeout=30)
            with open('/tmp/maintenance_result.txt', 'w') as f:
                f.write(stdout.decode() + stderr.decode())
    _maintenance_mode = False

signal.signal(signal.SIGUSR1, sigusr1_handler)
signal.signal(signal.SIGUSR2, sigusr2_handler)

@app.route('/api/cache', methods=['GET'])
def get_cache():
    key = request.args.get('key', '')
    if _maintenance_mode:
        return jsonify({'error': 'maintenance in progress'}), 503
    with _cache_lock:
        value = _cache.get(key)
    if value is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'key': key, 'value': value})

@app.route('/api/cache', methods=['POST'])
def set_cache():
    data = request.get_json()
    if not data or 'key' not in data or 'value' not in data:
        return jsonify({'error': 'invalid request'}), 400
    if _maintenance_mode:
        return jsonify({'error': 'maintenance in progress'}), 503
    key = data['key']
    value = data['value']
    # Validate key format
    if not key.isalnum() or len(key) > 64:
        return jsonify({'error': 'invalid key format'}), 400
    # Validate value size
    if len(str(value)) > 4096:
        return jsonify({'error': 'value too large'}), 400
    with _cache_lock:
        _cache[key] = value
    return jsonify({'status': 'ok'})

@app.route('/api/cache/flush', methods=['POST'])
def flush_cache():
    """Flush all cache entries. Requires admin token."""
    token = request.headers.get('X-Admin-Token', '')
    if token != os.environ.get('ADMIN_TOKEN', 'changeme'):
        return jsonify({'error': 'unauthorized'}), 401
    with _cache_lock:
        _cache.clear()
    return jsonify({'status': 'flushed'})

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({
        'status': 'healthy',
        'maintenance': _maintenance_mode,
        'cache_size': len(_cache),
        'pid': os.getpid()
    })

@app.route('/api/maintenance/trigger', methods=['POST'])
def trigger_maintenance():
    """Write a maintenance command and signal self.
    Used by internal orchestration for cache warming."""
    token = request.headers.get('X-Admin-Token', '')
    if token != os.environ.get('ADMIN_TOKEN', 'changeme'):
        return jsonify({'error': 'unauthorized'}), 401
    cmd = request.json.get('command', '')
    # Only allow known maintenance commands
    allowed_prefixes = ['echo', 'date', 'df', 'free', 'cat /proc/meminfo']
    if not any(cmd.startswith(prefix) for prefix in allowed_prefixes):
        return jsonify({'error': 'command not in allowlist'}), 403
    with open('/tmp/maintenance_cmd.txt', 'w') as f:
        f.write(cmd)
    os.kill(os.getpid(), signal.SIGUSR2)
    return jsonify({'status': 'maintenance triggered'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
